package com.friendinneed.timer;import java.time.Instant;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/profiles/{profileId}/timers") public class TimerController{private final TimerService service;public TimerController(TimerService s){service=s;}@GetMapping List<Timer> list(@PathVariable UUID profileId){return service.list(profileId);}@PostMapping @ResponseStatus(HttpStatus.CREATED) Timer create(@PathVariable UUID profileId,@RequestBody Request r){return service.create(profileId,r.label(),r.triggerAt());}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID profileId,@PathVariable UUID id){service.delete(profileId,id);}record Request(String label,Instant triggerAt){}}
